// ── B: the cast-ROUTING law — a minifloat cast lowers to the target's own
// conversion only for the decode direction on a target that decodes the
// format natively; every other direction stays the software codec. ──
fn slice_b321_cast_routing() -> Vec<KernelRule> {
    vec![
        KernelRule {
            rule_id: "minifloat-cast-routing-native-vs-software-by-target-direction"
                .to_string(),
            gpu_concept: "MECHANISM (the minifloat cast-ROUTING law at the pass level; category B — Compute, the cast-path lowering family beside gpu_144's word-conversion law): a minifloat cast lowers to the TARGET's own conversion instruction iff (a) the target decodes that format natively AND (b) the cast is the DECODE direction — from a minifloat to a non-minifloat float. Every other direction — ENCODING into a minifloat, casts to bool/integer, minifloat-to-minifloat — takes the software codec, whichever the target. The dispatch is per-(arch, format, direction), never per-format: sm_89 gives `cvt.rn.f16x2.e4m3x2` — one instruction per pair — for the decode direction only. Source: tracel-ai/cubecl @ 6bff8ad4 #2008 (Apache-2.0 OR MIT). THE DIRECTION GATE, verbatim [in-diff] shared/native_decode.rs `decoded_by` doc + body: 'The format a cast from `input` to `result` decodes, where it is a decode: from one of these formats to a float that is not a minifloat itself. A cast to a `bool` or an integer, or between minifloats, is the software codec's whichever the target.' — `let to_float = result.scalar_ty(ctx).is_float(ctx) && Self::of_type(ctx, result).is_none() && Fp8Format::of_type(ctx, result.scalar_ty(ctx)).is_none(); Self::of_type(ctx, input).filter(|_| to_float)`. THE PER-ARCH TABLE, verbatim [in-diff] `native_decodes(arch)`: 'The minifloats `arch` decodes itself. The PTX ISA gives `cvt.rn.f16x2.e4m3x2` and `cvt.rn.f16x2.e5m2x2` to `sm_89` on, and `cvt.rn.f16x2.e2m1x2` to the architecture-specific targets of `sm_100`, `sm_110` and `sm_120` and their minor versions' — `100..130 => &[E2M1x2, E4M3, E5M2], 89.. => &[E4M3, E5M2], _ => &[]`. THE PASS SWAP, verbatim [in-diff] `add_codec_passes` doc: 'Adds the passes lowering the minifloat casts a target decoding `native` itself does not.' — the fp8 arm swaps `LowerMinifloatCastPass` for `MatchRewritePass::new(LowerSoftwareMinifloatCast { codec, native })` when the target decodes either fp8 format, and the fp4 arm does the mirror (`LowerSoftwareFp4Cast` under `MatchRewritePass` when E2M1x2 is native, `LowerFp4CastPass` otherwise); the software filter, verbatim [in-diff] `LowerSoftwareMinifloatCast::r#match`: `(fp8(input) && !decoded) || fp8(result)` — an fp8 INPUT the target decodes is left native, everything else through the codec. THE ENUM GENERALIZATION: the fp4-only `Fp4Decode::{Native, Software}` becomes `NativeDecode {E2M1x2, E4M3, E5M2}` — the set of minifloats a target decodes itself, queried as a slice (`fn native_decodes(&self) -> &'static [NativeDecode]`), not one bool per format. THE NO-FP6 HALF is the removal decision, verbatim [commit-message]: 'LLVM: advertise no fp6 format, which no cast lowers' — fp6 (e2m3/e3m2) has no native decode anywhere and the backend has no lowering for a cast from or to either, so `restrict_common` takes both formats away instead of shipping a broken surface. WHY THE DIRECTION ASYMMETRY IS LOAD-BEARING: a decode is a widening fan-out (one code byte → floats) the hardware pair-conversion serves directly at full width; an encode is a narrowing convergence the hardware instruction does not offer, and minifloat-to-minifloat composes two decodes — forcing any of them through a native-decode-only assumption mis-lowers. Distinct from word-native-byte-pair-minifloat-conversion (gpu_144, N — WHICH instructions MOVE the pairs once conversion is chosen, the byte-select axis; THIS is which CASTS the pass leaves native at all — compose, never merge), from c-fragment-to-a-operand-register-repack (gpu_38 — the pair-decode MECHANICS inside an MMA operand path; THIS is the ROUTING predicate over arch × format × direction decided BEFORE any mechanic runs), from the exact-widening family (storage-form widening licenses; THIS widens float formats through hardware conversions), and from partial-constant-float-fold-ieee-unsound (gpu_116 — host-side constant folding soundness; THIS is device cast lowering). NotBenchable here (LLVM/NVPTX lowering dispatch; the direction gate, the arch table, and the pass-swap predicate are CPU-testable and ARE the fixtures). Batch 321 / Plan 321.".to_string(),
            ref_shape: "// naive: routing keys on the FORMAT alone — every cast touching a\n// minifloat goes through the software codec (or, worse, through the\n// native decode on BOTH directions)\nfn lower_minifloat_cast(input: Type, result: Type) -> Cast {\n    if let Some(_format) = minifloat_of(input) {\n        // every direction through the codec: the sm_89 decode pays the\n        // software path the hardware cvt.rn.f16x2.e4m3x2 serves in one\n        // instruction per pair\n        software_codec(input, result)\n    } else {\n        plain_cast(input, result)\n    }\n}".to_string(),
            opt_pattern: "// optimized: per-(arch, format, direction) routing — the native\n// conversion ONLY for the decode direction on a target that decodes the\n// format natively; every other direction keeps the software codec\nfn native_decodes(arch: &Arch) -> &'static [NativeDecode] {\n    match arch.version() {\n        100..130 => &[NativeDecode::E2M1x2, NativeDecode::E4M3, NativeDecode::E5M2],\n        89.. => &[NativeDecode::E4M3, NativeDecode::E5M2],\n        _ => &[],\n    }\n}\n\nfn decoded_by(input: Type, result: Type) -> Option<NativeDecode> {\n    // decode = minifloat input -> NON-minifloat float output; bool/int\n// destinations and minifloat-to-minifloat stay software\n    let to_float = result.is_float() && minifloat_of(result).is_none();\n    minifloat_of(input).filter(|_| to_float)\n}\n\nfn add_codec_passes(native: &[NativeDecode], passes: &mut Passes) {\n    let fp8_native = native.contains(&NativeDecode::E4M3)\n        || native.contains(&NativeDecode::E5M2);\n    if fp8_native {\n        // only the casts the target does NOT serve go to the codec\n        passes.add_rewrite(software_fp8_cast_unless(native));\n    } else {\n        passes.add_pass(lower_all_fp8_casts());\n    }\n}".to_string(),
        },
    ]
}

// ── B: a block-scaled mma's scale register OWNS the rows its unit works —
// the byte/unit selectors zero as the C++ backend's {0, 0}; the supported
// form refuses loud with the config named. ──
fn slice_b321_scale_register() -> Vec<KernelRule> {
    vec![KernelRule {
        rule_id: "block-scaled-mma-scale-register-owns-its-rows".to_string(),
        gpu_concept: "MECHANISM (block-scaled MMA scale-register ownership; category B — Compute, the MMA instruction family): on a block-scaled MMA lowering, EACH unit's scale register holds the scales of the rows that unit owns — packed one register per scale operand with the byte and unit selectors ZERO — never a per-row selector scheme, never a scale staging pass through shared memory. Source: tracel-ai/cubecl @ a4616247 #1995 (Apache-2.0 OR MIT). THE LAW, verbatim [in-diff] `mma_manual_scaled` doc: 'The intrinsic names its scale type, the scales a register holds and the kind that pairs them: `mxf4nvf4` both for MXFP4, two `ue8m0` scales, and for NVFP4, four `ue4m3` ones. Each unit's scales are one register; the byte and unit selectors are zero, as the C++ backend's `{0, 0}`: a unit's register holds the scales of the rows it owns.' THE LOWERING IS THE LAW MADE CODE, verbatim [in-diff]: for each scale operand `args.push(scales_word(ctx, rw, scales));` then `args.extend((0..2).map(|_| insert_int_const(ctx, rw, 16, 0)));` — ONE scale word + TWO zero i16 constants per operand (byte selector, unit selector), the literal `{0, 0}` of the C++ backend's block-scaled mma ABI. THE ACCUMULATOR IS FIXED f32, verbatim [in-diff]: the intrinsic name spells `.f32.e2m1.e2m1.f32.` and the guard demands `cd_elem.is_float32(ctx)` — e2m1 operands, e2m1 weights, f32 accumulator, no substitute. THE SCALE KIND PAIRS WITH THE FACTOR, verbatim [in-diff] the `scale` match: `2 => scale_type_name(...).filter(|name| *name == \"ue8m0\"), 4 => scale_type_name(...), _ => None` — factor 2 (MXFP4) demands ue8m0; factor 4 (NVFP4) accepts ue4m3 or ue8m0; any other factor refuses. THE SUPPORTED-FORM REFUSAL is loud with the config named, verbatim [in-diff]: `#[error(\"the NVPTX backend lowers the block-scaled `mma` on `e2m1x2` pairs scaled two or four times along `k` (MXFP4, NVFP4) only, not {0}\")] pub struct ScaledMmaUnsupported(String);` where the payload is the offender's own config — `format!(\"{} x {} into {}, {} scales, {factor} along k\", a_elem.disp(..), b_elem.disp(..), cd_elem.disp(..), scale_elem.disp(..))` — and the let-else `let (true, true, true, Some(scale)) = (pairs(a_elem), pairs(b_elem), cd_elem.is_float32(ctx), scale) else { ... return input_err!(op.loc(ctx), ScaledMmaUnsupported(config)); }` refuses BEFORE any register work. WHY ONE REGISTER PER UNIT: the hardware instruction reads scales as a per-unit operand word — a selector scheme (byte index, unit index) would add per-tile selector arithmetic the instruction ABI zeroes anyway, and staging scales through memory would re-read what the register layout already places in each unit's hands. Distinct from block-scaled-operand-declared-form-refusal-ladder (gpu_144, B — the DECLARED-FORM axis: what each operand's stored codes/words/scales must BE, refusals per axis; THIS is the scale-REGISTER ownership + packing axis and its supported-form ADMISSION refusal — the two faces of 'the instruction defines the contract', compose never merge; THIS batch carries the ScaledMmaUnsupported admission face ON that rule), from mma-accumulator-run-as-one-operand-depth-matches-instruction (gpu_141, B — the accumulator RUN-DEPTH axis; THIS is the scale-operand axis), from dpas-block-scale-after-accumulate-not-in-operand (gpu_102 — WHERE the scale applies, Intel DPAS post-accumulate; THIS is the NVPTX in-operand scale register), and from superblock-scale-replication-to-subblock-scale-slots (gpu_89 — scale-slot LAYOUT for the tiled path; THIS is the register-ownership contract of the instruction path). NotBenchable here (Blackwell-class `llvm.nvvm.mma.block.scale` intrinsic lowering; the selector-zero contract, the factor/scale-kind pairing, and the refusal payload are CPU-testable and ARE the fixtures). Batch 321 / Plan 321.".to_string(),
        ref_shape: "// naive: scales staged like any operand — selectors guessed, kinds\n// assumed, wrong configs silently mis-lowered\nfn lower_scaled_mma(op: &ScaledMma) -> Result<Args> {\n    let mut args = vec![];\n    args.extend(registers(op.a));\n    args.extend(registers(op.b));\n    // scale word + selectors invented ad hoc; factor/scale-kind never\n// cross-checked; an e4m3 scale at factor 2 lowers to garbage\n    args.push(scale_word(op.scales_a));\n    args.push(selector(op.scales_a)); // wrong: ABI zeroes this\n    Ok(Args(args))\n}".to_string(),
        opt_pattern: "// optimized: one scale register per unit, selectors ZERO as the C++\n// backend's {0, 0}; the supported form refuses loud with the config\nfn lower_scaled_mma(op: &ScaledMma) -> Result<Args> {\n    // the admission gate FIRST: e2m1x2 pairs, f32 accumulator, factor\n// 2 with ue8m0 scales or factor 4 with ue4m3/ue8m0 — anything else\n// refuses with the offender's own config named\n    let scale = match op.factor {\n        2 => scale_name(op.scales).filter(|n| n == \"ue8m0\"),\n        4 => scale_name(op.scales),\n        _ => None,\n    };\n    let (true, true, true, Some(scale)) = (pairs(op.a), pairs(op.b),\n        op.acc.is_f32(), scale) else {\n        return Err(ScaledMmaUnsupported(format!(\n            \"{} x {} into {}, {} scales, {} along k\",\n            op.a, op.b, op.acc, op.scales, op.factor)));\n    };\n    let mut args = vec![];\n    args.extend(registers(op.a));\n    args.extend(registers(op.b));\n    for scales in [op.scales_a, op.scales_b] {\n        args.push(scale_word(scales));            // ONE register of scales\n        args.push(0i16);                          // byte selector = 0\n        args.push(0i16);                          // unit selector = 0\n    } // the register holds the scales of the rows this unit owns\n    Ok(Args(args))\n}".to_string(),
    }]
}

// ── B: a span view takes its extent at the planning-granularity boundary —
// a partial view must plan its K split exactly as the whole head does. ──
fn slice_b321_span_view_planning() -> Vec<KernelRule> {
    vec![KernelRule {
        rule_id: "exl3-span-view-plans-at-planning-granularity".to_string(),
        gpu_concept: "MECHANISM (span-view planning consistency; category B — Compute, the quantized-weight planning family): when a kernel's launch plan is a pure function of the matrix SHAPE (`plan(k, n, ...)` — K-split width and work-tile count derived from the column-block count), a PARTIAL view of that matrix must take its extent at the PLANNING GRANULARITY BOUNDARY — the view width at which `plan()` returns the whole matrix's own plan — so the view's K split and its bit-level behavior are IDENTICAL to the whole head's; a sub-granularity view changes the plan (a 384-column tail planned eight K splits where the full head plans one) and DIVERGES NUMERICALLY — its logits and the proposals drawn from them change. Source: ashhart/TensorFold @ cef784e2 + 6a8dfec0 #1507 (the #1465-series EXL3 head lane; Apache-2.0). THE GRANULARITY CONSTANT, verbatim [in-diff] exl3.zig: '/// From this many 128-column blocks a shape plans one K split, so a view that wide keeps the whole matrix's bits.' + `pub const wide_blocks = 64;` — 64 × 128-column blocks = column 240,128 of the 248,320-column head; `plan()` itself keys on the same constant, verbatim [in-diff]: `var wk: usize = if (nb >= wide_blocks) 8 else 4;` + `if (nb < wide_blocks) { while (nb * sk < blocks and sk < 64) sk *= 2; }` (the nb < wide_blocks ladder that produced the tail's different plan). THE VIEW CONTRACT, verbatim [in-diff] cuda_draft_frame.zig: '/// An EXL3 head's tail view: the last wide_blocks blocks (from row 240,128), so it plans as the whole head does.' THE REGRESSION TEST pins the equivalence, verbatim [in-diff] qwen35_draft_frame_host.zig: `test \"Draft frames: an EXL3 head's span views plan their K split as the whole head does\"` — `const whole = x3.plan(w.k, w.n, 192, 8); try std.testing.expectEqual(whole, x3.plan(v.first.k, v.first.n, 192, 8)); try std.testing.expectEqual(whole, x3.plan(v.tail.k, v.tail.n, 192, 8));` — BOTH span views assert plan-equality with the whole, plus the coverage pin `try std.testing.expect(F.x3_tail_at <= 248032 and F.x3_tail_at + v.tail.n == w.n)` (the tail ends exactly at the matrix edge — the views PARTITION the head, no gap, no overlap). THE DEFECT IT REPLACES, verbatim [commit-message cef784e2]: 'The 384-column tail planned eight K splits where the full head plans one, so its logits and some proposals changed. The view now starts at column 240,128 (exl3.wide_blocks blocks), keeping #1465's bits.' THE CONSUMER, verbatim [commit-message 6a8dfec0]: the DFlash2 drafter 'projects only the spans it proposes from, as column views of the stored matrix: exl3.Weight.columns keeps the parent's strides and moves to whole 128-column blocks, with a host test' — view creation itself snaps to whole 128-column blocks, the granularity HALF of the planning boundary. WHY NOT RE-PLAN THE VIEW: the plan is shape-pure so row bits never depend on the row count (the in-source law 'from the shape alone so a row's bits never depend on the row count') — letting a view plan differently would fork the bit-stream between full-head and view executions of the same weights; snapping the VIEW to the planning boundary keeps ONE plan for ONE matrix regardless of how it is consumed. Distinct from hardcoded-fast-path-jit-specialization + static-sibling-with-shape-check (gpu_12 — shape SPECIALIZATION with an identical-results fallback; THIS is the VIEW-EXTENT side: consume a matrix partially only at widths that preserve the whole's plan), from derive-shape-from-payload-not-cached-field (B31 — the truth SOURCE of a shape; THIS is which PARTIAL EXTENTS may be consumed), from occupancy-keyed-value-split-register-budget-ladder (gpu_94 — the plan CONTENT: how occupancy picks K splits; THIS is the view-consumption precondition that the same plan applies), and from moe-weights-load-time-soa-accumulation-order-pinned (gpu_104 — accumulation ORDER pinning; THIS is planning-EQUIVALENCE pinning across views). NotBenchable here (planning-equivalence axis; the plan-equality assertion and the partition coverage are CPU-testable and ARE the fixtures). Batch 321 / Plan 321.".to_string(),
        ref_shape: "// naive: a drafter projects only the columns it proposes from — the\n// view takes its natural extent, whatever that is\nfn tail_view(w: &Weight) -> View {\n    let at = w.n - 384; // a 384-column tail: nb = 3 < wide_blocks\n    View { k: w.k, n: w.n - at, stride: w.stride_k, at }\n    // plan(v) diverges: nb=3 runs the sk ladder the whole head (nb=1940)\n// never touches — 8 K splits where the whole plans ONE; the tail's\n// logits and the proposals drawn from them change bits\n}".to_string(),
        opt_pattern: "// optimized: the view snaps to the planning-granularity boundary —\n// the width at which plan() returns the whole matrix's own plan\npub const wide_blocks: usize = 64; // 64 x 128-col blocks: one K split\n\nfn tail_view(w: &Weight) -> View {\n    let at = w.n - wide_blocks * 128; // the last 64 blocks, verbatim\n    View { k: w.k, n: w.n - at, stride: w.stride_k, at }\n}\n\n// the host test pins BOTH views' plan-equality with the whole:\n//   let whole = plan(w.k, w.n, 192, 8);\n//   assert_eq!(whole, plan(v.first.k, v.first.n, 192, 8));\n//   assert_eq!(whole, plan(v.tail.k, v.tail.n, 192, 8));\n//   assert!(TAIL_AT <= edge && TAIL_AT + v.tail.n == w.n); // partition\nfn plan(k: usize, n: usize, blocks: usize, min_tiles: usize) -> Plan {\n    let nb = n / 128;\n    let wk = if nb >= wide_blocks { 8 } else { 4 };\n    // ... the shape-pure ladder — ONE plan per matrix, every consumer\n}".to_string(),
    }]
}

// ── C: at a comms boundary, fuse the consumer's elementwise chain (norm →
// quant) INTO the gather kernel — one remote-data pass, fallback separate. ──
fn slice_b321_comms_fusion() -> Vec<KernelRule> {
    vec![KernelRule {
        rule_id: "comms-boundary-consumer-chain-fuses-into-gather".to_string(),
        gpu_concept: "MECHANISM (the comms-boundary fusion law; category C — Fusion, the collectives arm): when a collective's output (all-gather, all-to-all, reduce) feeds a FIXED elementwise chain (normalize → quantize is the serving shape), the chain FUSES INTO the gather consumer — one pass over the remote data as it lands, producing the quantized tensor directly — instead of materializing the gathered tensor, then a separate norm kernel, then a separate quant kernel; the fused arm is TRIED FIRST and the separate-op path is the FALLBACK (armed when the fused kernel is unavailable or the layer's fusion preconditions drop), never the default. Source: vllm-project/vllm @ becbaea9f #64638 (Apache-2.0). THE FUSED-FIRST DISPATCH, verbatim [in-diff] mega_moe.py `pool_and_quantize`: `if fused := self._all_gather_norm_quant(pooled, norm, self.experts.nvfp4_input_global_scale): return None, fused` then the fallback `pooled = sp_all_gather(pooled)` feeding `prepare_decode_inputs(pooled, norm, buffer, num_tokens)` — the walrus-armed try-first, the gather-then-separate chain only when the fused arm declines. THE PRECONDITION SET is per-layer declared, verbatim [in-diff] `_configure_pooler_gather`: the fused config arms only on layers where `layer.feed_forward.shard_pooler and (layer.feed_forward.fused_input_quant or layer.feed_forward.use_hybrid_moe) and layer.feed_forward.norm_fuses_into_nvfp4_quant` — fusion is a DECLARED capability of the layer stack, not a runtime guess. THE ELISION SIDE: the fused return is `(None, fused)` — the unfused pooled tensor is never materialized at all on the fused path (the gather's output lands straight in the norm+quant kernel's output buffer); on the fallback path the gathered tensor IS the product. THE PARITY FACE: both paths must agree bit-wise on the quantized payload (the fused kernel computes the norm it quantizes under the same variance path the separate `prepare_*` pair does — the NVFP4 global scale is the shared constant). WHY THE FUSION PAYS: the gathered tensor is remote-data-heavy (the full activation set crosses the wire); each separate kernel re-reads it from memory — norm reads it, quant reads the normed copy — while the fused kernel reads each element ONCE from the comms landing zone and writes only the packed output, removing two full-size round trips per layer boundary. Distinct from moe-group-selection-fused-into-topk (gpu_125-era, B — fusing the ROUTE computation into topk; THIS fuses the post-COLLECTIVE elementwise chain into the collective consumer), from same-input-projection-pair-in-one-dispatch (gpu_117, C — N projections of ONE input share a dispatch; THIS is one chain over COLLECTIVE output), from all-reduce-eager-batched-rank-order (the determinism family — rank-order folds for bit-reproducibility; THIS is a fusion-of-consumer law and pins the same norm math both arms), and from rms-norm-registers-carry-x-between-passes (gpu_104, A — the norm's x stays in registers ACROSS passes in one kernel; THIS removes the passes at the comms boundary). NotBenchable here (serving-stack fusion dispatch; the fused-first ordering, the precondition gate, and the fallback parity are CPU-testable and ARE the fixtures). Batch 321 / Plan 321.".to_string(),
        ref_shape: "// naive: gather, then run the consumer chain kernel-by-kernel over the\n// materialized tensor\nfn layer_boundary_unfused(hidden: &Tensor, buffer: &Buffer, norm: &Norm) -> Quantized {\n    let pooled = sp_all_gather(&pooler(hidden)); // the full activation set\n    // crosses AND materializes — three full-size touches per boundary:\n    // the gather write, the norm read, the quant read of the normed copy\n    let normed = rms_norm(&pooled, norm, /* separate kernel */);\n    quantize_nvfp4(&normed, buffer) // a third dispatch over remote data\n}".to_string(),
        opt_pattern: "// optimized: the chain fuses INTO the gather consumer — one pass over\n// the remote data; the separate path is the FALLBACK, never the default\nfn layer_boundary(hidden: &Tensor, buffer: &Buffer, norm: &Norm, gs: f32) -> Quantized {\n    // arming is a DECLARED per-layer capability, not a runtime guess:\n    //   shard_pooler && (fused_input_quant || use_hybrid_moe)\n    //   && norm_fuses_into_nvfp4_quant\n    if let Some(fused) = all_gather_norm_quant(hidden, norm, gs) {\n        return fused; // the unfused pooled tensor is never materialized\n    }\n    // fallback: gather only; the declared-precondition arm keeps parity\n    let pooled = sp_all_gather(&pooler(hidden));\n    prepare_decode_inputs(&pooled, norm, buffer)\n}".to_string(),
    }]
}

pub fn entries() -> Vec<KernelRule> {
    let mut out = Vec::new();
    out.extend(slice_b321_cast_routing());
    out.extend(slice_b321_scale_register());
    out.extend(slice_b321_span_view_planning());
    out.extend(slice_b321_comms_fusion());
    out
}
